const input = $input.first().json;
const userMessage = String(input.chatInput ?? '').trim();

if (!userMessage) {
  throw new Error('chatInput is empty');
}

const systemPrompt = [
  'Ты локальный Codex-агент проекта Automation Workbench.',
  'Работай только внутри текущего allowlisted repository.',
  'Перед действиями прочитай AGENTS.md и релевантный файл сценария.',
  'Не записывай секреты, cookies, credentials или runtime в Git.',
  'Не изменяй файлы, если пользователь просит только объяснить, проверить или диагностировать.',
  'Если пользователь просит изменение, выполни его, проверь результат и кратко сообщи созданные файлы.',
  'Для website availability используй scenarios/website-availability/SCENARIO.md.',
].join('\n');

return [{
  json: {
    ...input,
    prompt: `${systemPrompt}\n\nСообщение пользователя:\n${userMessage}`,
  },
}];

const result = $input.first().json;
const finalOutput = String(result.final_output ?? '').trim();
const fallback = result.error
  ? `Codex adapter error: ${result.error}`
  : 'Codex завершил запрос без текстового ответа.';

return [{
  json: {
    output: finalOutput || fallback,
  },
}];

const instructionFile = 'scenarios/website-availability/RUN_PROMPT.md';
const scenarioFile = 'scenarios/website-availability/SCENARIO.md';
const inputFile = 'scenarios/website-availability/sites.json';
const action = [
  'Проверить все environments из input_file.',
  'Для каждого environment сохранить HTTP-результат и screenshot.',
  'Создать report.md и report.json в новой папке runs/<run-id>/.',
  'Отправить report.json в локальный n8n evidence gate.',
  'Не переходить к функциональным проверкам без полного PASS.',
].join(' ');

const prompt = [
  'Запусти сценарий по кнопке n8n.',
  'Сначала прочитай AGENTS.md.',
  `Прочитай основной prompt: ${instructionFile}`,
  `Прочитай описание сценария: ${scenarioFile}`,
  `Используй входные данные: ${inputFile}`,
  `Задача: ${action}`,
  'Следуй указанным файлам как источнику истины.',
  'Если обязательный инструмент недоступен, не подделывай evidence: верни BLOCKED и точную причину.',
].join('\n');

return [{
  json: {
    trigger: 'manual_button',
    instruction_file: instructionFile,
    scenario_file: scenarioFile,
    input_file: inputFile,
    action,
    prompt,
  },
}];

const result = $input.first().json;

return [{
  json: {
    ok: Boolean(result.ok),
    request_id: result.request_id ?? null,
    duration_ms: result.duration_ms ?? null,
    result: String(result.final_output ?? result.error ?? '').trim(),
  },
}];
